import { test, expect } from '@playwright/test';

test.describe('Table Row Hover Highlight', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table');
  });

  test('should highlight a row when hovered', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Get the first row using getByRole('row')
    const firstRow = page.getByRole('row', { name: /first row/i });
    await expect(firstRow).toBeVisible();

    // Hover over the first row
    await firstRow.hover();

    // Verify the row has a highlight class
    await expect(firstRow).toHaveClass(/highlighted-row/);

    // Verify the highlight class is applied to the row element
    const rowElement = page.locator('[data-testid="first-row"]');
    await expect(rowElement).toHaveClass(/highlighted-row/);

    // Verify the highlight color is visible
    const highlightColor = page.locator('[data-testid="first-row"]').first();
    await expect(highlightColor).toHaveCSS('background-color', /rgba\(255, 255, 255, 0.1\)/);

    // Verify the row content is still visible
    const rowContent = page.locator('[data-testid="first-row"]');
    await expect(rowContent).toBeVisible();
  });

  test('should remove highlight when hover ends', async ({ page }) => {
    // Get the second row using getByRole('row')
    const secondRow = page.getByRole('row', { name: /second row/i });
    await expect(secondRow).toBeVisible();

    // Hover over the second row
    await secondRow.hover();

    // Verify the row has a highlight class
    await expect(secondRow).toHaveClass(/highlighted-row/);

    // Verify the highlight color is visible
    const highlightColor = page.locator('[data-testid="second-row"]').first();
    await expect(highlightColor).toHaveCSS('background-color', /rgba\(255, 255, 255, 0.1\)/);

    // Remove hover by moving mouse away
    await page.mouse.move(50, 50);

    // Wait for highlight to be removed
    await page.waitForTimeout(100);

    // Verify the highlight class is removed
    await expect(secondRow).not.toHaveClass(/highlighted-row/);

    // Verify the highlight color is removed
    await expect(highlightColor).not.toHaveCSS('background-color', /rgba\(255, 255, 255, 0.1\)/);
  });
});
